 Future<void> load() async {final c=(widget.companyId??'').trim();if(db==null||c.isEmpty){if(mounted)setState(()=>error='لا توجد شركة نشطة أو اتصال بقاعدة البيانات.');return;}setState(()=>loading=true);try{final x=await db!.from('erp_geographic_data').select('id,parent_id,geo_code,name_ar,name_en,level,is_active,logo_url,source_name,source_url,latitude,longitude').eq('company_id',c).order('geo_code');if(!mounted)return;setState(() { rows=(x as List).map((e)=>Map<String,dynamic>.from(e)).toList(); loading=false; error=null; });}catch(e){if(mounted)setState(() { loading=false; error='تعذر تحميل البيانات من قاعدة البيانات: $e'; });}}
