 @override Widget build(BuildContext context)=>Directionality(textDirection:TextDirection.rtl,child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Card(color:const Color(0xFF3E007D),child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('بيانات جغرافية',style:TextStyle(color:Colors.white,fontSize:21,fontWeight:FontWeight.w900)),const Text('شجرة المحافظات ثم الأحياء والمراكز ثم المناطق والقرى والشياخات، مع تحميل الفروع عند فتحها.',style:TextStyle(color:Colors.white70)),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:[task('تحديث',Icons.refresh,Colors.blue,loading?null:load),task('إضافة محافظة',Icons.add_location_alt,const Color(0xFF168447),()=>edit(level:'governorate')),task('معاينة',Icons.preview_outlined,const Color(0xFFFFA015),()=>showDialog<void>(context:context,builder:(ctx)=>AlertDialog(title:const Text('معاينة'),content:Text('عدد السجلات: '+rows.length.toString()),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('إغلاق'))])))]))]))),if(error!=null)Text(error!,style:const TextStyle(color:Colors.red)),if(message!=null)Text(message!,style:const TextStyle(color:Colors.green)),if(loading)const LinearProgressIndicator(),Padding(padding:const EdgeInsets.symmetric(horizontal:8,vertical:4),child:Text('المحافظات: ${rows.where((r)=>s(r[\'level\'])==\'governorate\').length}  •  الأحياء/المراكز: ${rows.where((r)=>s(r[\'level\'])==\'district\').length}  •  المناطق/القرى: ${rows.where((r)=>s(r[\'level\'])==\'area\').length}  •  إجمالي السجلات: ${rows.length}',style:const TextStyle(color:Color(0xFF3E007D),fontWeight:FontWeight.w700))),Expanded(child:rows.isEmpty&&!loading?Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.location_off_outlined,size:48,color:Color(0xFF9B91A8)),const SizedBox(height:10),Text(error==null?'لا توجد بيانات جغرافية مسجلة لهذه الشركة حتى الآن. اضغ